async (page) => {
 const started = new Date().toISOString();
 const browser = page.context().browser();
 const hosts = {resident:'https://ca-resident-demo.happyriver-ace49996.uksouth.azurecontainerapps.io',employee:'https://ca-cutover-test-demo-api.happyriver-ace49996.uksouth.azurecontainerapps.io'};
 const results=[];
 const check=(value,message)=>{if(!value)throw new Error(message);};
 for(const viewport of [{width:1365,height:900},{width:390,height:844}]) {
  for(const [kind,base] of Object.entries(hosts)) {
   const context=await browser.newContext({viewport});
   try {
    const p=await context.newPage(); const requests=[]; const responses=[]; const pending=[]; const consoleErrors=[]; const pageErrors=[];
    const safePath=url=>{const u=new URL(url);return u.pathname+(u.searchParams.has('v')?'?v='+u.searchParams.get('v'):'');};
    p.on('request',r=>{if(new URL(r.url()).origin===base)requests.push({method:r.method(),path:safePath(r.url())});});
    p.on('response',r=>{if(new URL(r.url()).origin===base)pending.push(r.allHeaders().then(h=>responses.push({path:safePath(r.url()),status:r.status(),cacheControl:h['cache-control']||null})));});
    p.on('console',m=>{if(m.type()==='error')consoleErrors.push('browser_console_error');});
    p.on('pageerror',()=>pageErrors.push('browser_page_error'));
    const health=await context.request.get(base+'/healthz',{timeout:180000,maxRedirects:0}); check(health.status()===200,kind+' health');
    const shell=await p.goto(base+'/',{waitUntil:'networkidle',timeout:180000});check(shell.status()===200,kind+' public shell');
    const htmlHeader=(await shell.allHeaders())['cache-control'];check(htmlHeader==='no-store',kind+' html no-store');
    const urls=await p.evaluate(()=>[...document.querySelectorAll('script[src],link[href],img[src]')].map(e=>e.getAttribute('src')||e.getAttribute('href')).filter(u=>u&&u.startsWith('/')&&/\.(js|css|png|svg)(\?|$)/.test(u)));
    check(urls.length>0&&urls.every(u=>new URL(u,base).searchParams.has('v')),kind+' versioned urls');
    const assets=[];for(const url of urls){const r=await context.request.get(base+url,{timeout:180000,maxRedirects:0});const h=r.headers()['cache-control'];check(r.status()===200,kind+' asset200');check(h&&h.split(',').map(s=>s.trim()).includes('max-age=31536000')&&h.split(',').map(s=>s.trim()).includes('immutable'),kind+' immutable');assets.push({path:url,status:r.status(),cacheControl:h});}
    const result={kind,viewport,health:health.status(),public:shell.status(),htmlCacheControl:htmlHeader,versionedUrls:urls,assets};
    if(kind==='resident') {
     const launcher=p.getByRole('button',{name:'Chat',exact:true});await launcher.waitFor({state:'visible'});await launcher.click();
     const dialog=p.getByRole('dialog');await dialog.waitFor({state:'visible'});result.open=await dialog.isVisible();
     await dialog.locator('summary').filter({hasText:'Chat size'}).click();
     const dock=dialog.getByRole('button',{name:'Dock to right edge',exact:true});await dock.click();
     await p.waitForFunction(()=>document.querySelector('.chat-widget').classList.contains('chat-widget-docked'));
     result.docked=await dialog.evaluate(el=>({classPresent:el.classList.contains('chat-widget-docked'),height:el.getBoundingClientRect().height,width:el.getBoundingClientRect().width,heightControlDisabled:el.querySelector('input[name="height"]').disabled,dockPressed:el.querySelector('button[aria-pressed]').getAttribute('aria-pressed'),launcherHidden:document.querySelector('.chat-widget-launcher').hidden}));
     check(result.docked.classPresent&&result.docked.heightControlDisabled&&result.docked.dockPressed==='true'&&result.docked.launcherHidden&&Math.abs(result.docked.height-viewport.height)<2,'resident dock state');
     await dock.click();await p.waitForFunction(()=>!document.querySelector('.chat-widget').classList.contains('chat-widget-docked'));
     result.undocked=await dialog.evaluate(el=>({classAbsent:!el.classList.contains('chat-widget-docked'),heightControlEnabled:!el.querySelector('input[name="height"]').disabled,dockPressed:el.querySelector('button[aria-pressed]').getAttribute('aria-pressed'),launcherVisible:!document.querySelector('.chat-widget-launcher').hidden}));
     check(result.undocked.classAbsent&&result.undocked.heightControlEnabled&&result.undocked.dockPressed==='false'&&result.undocked.launcherVisible,'resident undock state');
     await p.keyboard.press('Escape');await dialog.waitFor({state:'hidden'});result.escapeClosed=!(await dialog.isVisible());check(result.escapeClosed,'resident Escape');
     check(urls.some(u=>u.startsWith('/chat-widget.js?v='))&&urls.some(u=>u.startsWith('/chat-widget.css?v=')),'resident widget references');
    } else {
     const denied=await context.request.get(base+'/app',{timeout:180000,maxRedirects:0});check([302,401].includes(denied.status()),'employee anonymous denial');
     const location=denied.headers()['location'];result.protected={status:denied.status(),redirectOrigin:location?new URL(location,base).origin:null};
    }
    result.noHorizontalOverflow=await p.evaluate(()=>document.documentElement.scrollWidth<=innerWidth);
    await Promise.all(pending);result.requests=requests;result.responses=responses;result.consoleErrorCount=consoleErrors.length;result.pageErrorCount=pageErrors.length;check(requests.every(r=>r.method==='GET'),'no submissions');
    result.anonymous=true;result.noSigninOrSubmission=true;results.push(result);
   } finally {await context.close();}
  }
 }
 return {started,finished:new Date().toISOString(),results,scope:'Fresh anonymous contexts; no sign-in or model request; no signed-in acceptance'};
}
